 * Longest-common-subsequence comparison between a side and the base it was
 * derived from, and the changes (runs of base lines replaced by runs of the
 * side's lines) that fall out of that comparison.
 */

/**
 * Builds the suffix-LCS-length table for `base` against `side`: `table[i][j]`
 * is the length of the longest common subsequence of `base[i:]` and
 * `side[j:]`. Stored flat for speed, indexed as `i * (n + 1) + j`.
 */
function lcsTable(base, side) {
  const m = base.length
  const n = side.length
  const width = n + 1
  const table = new Int32Array((m + 1) * width)
  for (let i = m - 1; i >= 0; i--) {
    const row = i * width
    const nextRow = (i + 1) * width
    for (let j = n - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        table[row + j] = table[nextRow + j + 1] + 1
      } else {
        const skipBase = table[nextRow + j]
        const skipSide = table[row + j + 1]
        table[row + j] = skipBase >= skipSide ? skipBase : skipSide
      }
    }
  }
  return table
}

/**
 * Walks `base` and `side` from the start, matching a line whenever the
 * current lines are equal and otherwise advancing whichever pointer keeps
 * the longer remaining subsequence achievable (base wins ties). Returns the
 * changes: runs of base lines the walk did not match, paired with the run of
 * `side` lines that replaces them. `side` is the label ('mine' or 'theirs')
 * attached to each change.
 */
export function computeChanges(base, side, label) {
  const m = base.length
  const n = side.length
  const width = n + 1
  const table = lcsTable(base, side)

  const changes = []
  let i = 0
  let j = 0
  let pendingI = 0
  let pendingJ = 0

  while (i < m && j < n) {
    if (base[i] === side[j]) {
      if (i > pendingI || j > pendingJ) {
        changes.push({ baseStart: pendingI, baseEnd: i, lines: side.slice(pendingJ, j), side: label })
      }
      i++
      j++
      pendingI = i
      pendingJ = j
    } else {
      const skipBase = table[(i + 1) * width + j]
      const skipSide = table[i * width + j + 1]
      if (skipBase >= skipSide) i++
      else j++
    }
  }

  if (pendingI < m || pendingJ < n) {
    changes.push({ baseStart: pendingI, baseEnd: m, lines: side.slice(pendingJ, n), side: label })
  }

  return changes
}
"}

