{"file_path":"src/merge.js","content":"/**
 * Groups the changes from both sides into regions and resolves each region
 * against mine, the base, and theirs.
 */

import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Reconstructs one side's lines across `[start, end)` of the base: base
 * lines stand where none of `changes` (that side's changes touching this
 * region, in base order) apply, and each change contributes its own lines
 * in place of the base run it replaces.
 */
function reconstruct(base, changes, start, end) {
  const result = []
  let cursor = start
  for (const change of changes) {
    if (change.baseStart > cursor) result.push(...base.slice(cursor, change.baseStart))
    result.push(...change.lines)
    cursor = change.baseEnd
  }
  if (cursor < end) result.push(...base.slice(cursor, end))
  return result
}

/**
 * Decides how a region resolves given its reconstructed mine, base, and
 * theirs lines. `kind` is one of `both`, `mine`, `theirs` or `conflict`;
 * `both` and `mine` both resolve to mine's lines, `theirs` resolves to
 * theirs's lines.
 */
function resolveRegion(mineLines, baseLines, theirsLines) {
  if (arraysEqual(mineLines, theirsLines)) return { kind: 'both', lines: mineLines }
  if (arraysEqual(mineLines, baseLines)) return { kind: 'theirs', lines: theirsLines }
  if (arraysEqual(theirsLines, baseLines)) return { kind: 'mine', lines: mineLines }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}

/**
 * Computes the ordered list of regions covering `base`: stable regions kept
 * unchanged, and regions resolved from the changes mine and theirs made
 * against the base.
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine, 'mine')
  const theirsChanges = computeChanges(base, theirs, 'theirs')
  const allChanges = [...mineChanges, ...theirsChanges].sort((a, b) => a.baseStart - b.baseStart)

  const regions = []
  let prevEnd = 0
  let idx = 0

  while (idx < allChanges.length) {
    const first = allChanges[idx]
    let start = first.baseStart
    let end = first.baseEnd
    const touching = [first]
    idx++
    while (idx < allChanges.length && allChanges[idx].baseStart <= end) {
      end = Math.max(end, allChanges[idx].baseEnd)
      touching.push(allChanges[idx])
      idx++
    }

    if (start > prevEnd) regions.push({ kind: 'stable', lines: base.slice(prevEnd, start) })

    const mineTouching = touching.filter(change => change.side === 'mine')
    const theirsTouching = touching.filter(change => change.side === 'theirs')
    const mineLines = reconstruct(base, mineTouching, start, end)
    const theirsLines = reconstruct(base, theirsTouching, start, end)
    const baseLines = base.slice(start, end)

    regions.push(resolveRegion(mineLines, baseLines, theirsLines))
    prevEnd = end
  }

  if (prevEnd < base.length) regions.push({ kind: 'stable', lines: base.slice(prevEnd, base.length) })

  return regions
}
"}

