 * Splits the raw standard input into the three documents (mine, base,
 * theirs) it holds.
 */

/**
 * Splits `input` on newlines, dropping the empty tail a trailing newline
 * leaves, then splits the resulting lines into documents wherever a line is
 * exactly `%%%`. Throws if the result is not exactly three documents.
 */
export function parseDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const documents = [[]]
  for (const line of lines) {
    if (line === '%%%') documents.push([])
    else documents[documents.length - 1].push(line)
  }

  if (documents.length !== 3) throw new Error('expected three parts separated by %%%')
  return documents
}
"}

