{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { parseDocuments } from './parse.js'
import { computeRegions } from './merge.js'
import { formatMerge, formatRegions } from './format.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.includes(mode)) {
    fail('usage: cli.js merge|merge2|regions')
  }

  let documents
  try {
    documents = parseDocuments(readFileSync(0, 'utf8'))
  } catch (error) {
    fail(error.message)
  }
  const [mine, base, theirs] = documents

  const regions = computeRegions(mine, base, theirs)
  const { lines, conflict } =
    mode === 'regions' ? formatRegions(regions) : formatMerge(regions, mode === 'merge')

  process.stdout.write(lines.length === 0 ? '' : `${lines.join('\n')}\n`)
  process.exit(conflict ? 1 : 0)
}

main()
"}

